(23, 6, 'C', 'Cancel the session without notice.', 0),
(24, 6, 'D', 'Ask the patient to book another appointment.', 0),
(25, 7, 'A', 'Stop the exercise and offer water, checking their vitals.', 1),
(26, 7, 'B', 'Ignore it and continue the session.', 0),
