(40, 10, 'D', 'Ignore the request and continue.', 0),
(41, 11, 'A', 'Report the issue to management.', 1),
(42, 11, 'B', 'Ignore it since it’s not your concern.', 0),
(43, 11, 'C', 'Confront the colleague and argue.', 0),
(44, 11, 'D', 'Support the colleague to avoid conflicts.', 0),
(45, 12, 'A', 'Stay professional, complete the session, and take a break later.', 1),
(46, 12, 'B', 'Stay professional, complete the session, and take a break later.', 1),
(47, 12, 'C', 'Cancel the next appointment without informing them.', 0),
(48, 12, 'D', 'Show frustration and tell the patient to hurry.', 0),
(49, 13, 'A', 'Respond professionally and offer to address concerns.', 1),
(50, 13, 'B', 'Argue with them online.', 0),
(51, 13, 'C', 'Argue with them online.', 0),
(52, 13, 'D', 'Argue with them online.', 0),
(53, 14, 'A', 'Listen to their concerns but follow professional guidelines.', 1),
(54, 14, 'B', 'Accept whatever they say, even if it’s unscientific.', 0),
(55, 14, 'C', 'Cancel the session if they don’t agree with you.', 0),
(56, 14, 'D', 'Let them dictate the treatment plan.', 0),
(57, 15, 'A', 'Use a playful, engaging method to build trust.', 1),
(58, 15, 'B', 'Force them to do the exercises.', 0),
