INSERT INTO `plans` (`id`, `title`, `description`, `type`, `duration`, `duration_type`, `price`, `benefits`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Basic Plan', 'Maximize your potential with premium support, training, and personalized mentorship for long-term success.', 'standard', 1, 'month', 3000.00, '[\"Access to basic tools\",\"Discount on  kits\",\"Email Support\"]', 1, '2025-06-12 05:37:58', '2025-06-12 05:41:04'),
(2, '3 year plan', 'Gain credibility and unlock exclusive resources designed to grow your physiotherapy practice.', 'standard', 3, 'year', 5000.00, '[\"Verification Badge\",\"Discount on kits\",\"Priority Support\",\"Exculisive webinars\"]', 1, '2025-06-12 05:39:15', '2025-06-12 05:41:16'),
(3, '5 Years Plan', 'Get started with essential tools and support to begin your physiotherapy journey confidently.', 'premium', 5, 'year', 9000.00, '[\"Verification Badge\",\"Discount on kits\",\"Priority Support\",\"Exculisive webinars\"]', 1, '2025-06-12 05:39:38', '2025-06-12 05:41:29');
