INSERT INTO `sections` (`id`, `title`, `description`) VALUES
(1, 'Empathy & Patient Handling', 'To evaluate how well the physiotherapist understands and connects with patients.'),
(2, 'Communication & Professionalism', 'To assess interpersonal skills and ethical conduct.'),
(3, 'Problem-Solving in Medical Scenarios', 'To check decision-making in critical situations.'),
(4, 'Ethics & Professional Boundaries', 'To ensure ethical decision-making.'),
(5, 'Stress Management & Patience', 'To evaluate handling difficult situations.'),
(6, 'Situational Judgment & Adaptability', 'To assess adaptability to situations and patient needs.');
